  function bindWork(){
    $('[data-suite145-back]',workHost)?.addEventListener('click',()=>workBack?.());$('[data-suite145-login]',workHost)?.addEventListener('click',()=>window.AiderDearFirebase?.login?.());
    $$('[data-work-mode]',workHost).forEach(b=>b.onclick=()=>{workMode=b.dataset.workMode;renderWork(workHost,workBack,workMode)});$$('[data-work-tab]',workHost).forEach(b=>b.onclick=()=>{workTab=b.dataset.workTab;renderWork(workHost,workBack,'work')});
    $$('[data-work-add]',workHost).forEach(b=>b.onclick=()=>workModal({},b.dataset.workAdd||(workTab==='today'?'tasks':workTab)));
    $('[data-work-search]',workHost)?.addEventListener('click',()=>{const value=prompt('업무·과제·실험·고객 검색',workQuery);if(value===null)return;workQuery=value;workMode='work';if(workTab==='today')workTab='tasks';renderWork(workHost,workBack,'work')});
    $$('[data-work-edit]',workHost).forEach(b=>b.onclick=()=>{const row=workData().workRecords.find(r=>r.id===b.dataset.workEdit);if(row)workModal(row,row.type)});
    $$('[data-work-delete]',workHost).forEach(b=>b.onclick=async()=>{if(!confirm('이 기록을 보관함에서도 완전히 삭제할까요?'))return;const p=workData();p.workRecords=p.workRecords.filter(r=>r.id!==b.dataset.workDelete);await save();renderWork(workHost,workBack,'work')});
    $$('[data-work-progress]',workHost).forEach(b=>b.onclick=async()=>{const r=workData().workRecords.find(x=>x.id===b.dataset.workProgress);if(!r)return;if(r.representativeChecked)r.status='완료';else r.status='실무 완료';r.updatedAt=Date.now();await save();renderWork(workHost,workBack,'work')});
    $$('[data-work-confirm]',workHost).forEach(b=>b.onclick=async()=>{const r=workData().workRecords.find(x=>x.id===b.dataset.workConfirm);if(!r)return;r.representativeChecked=true;r.status='완료';r.confirmedAt=Date.now();await save('대표 확인 후 최종 완료했습니다.');renderWork(workHost,workBack,'work')});
    $('[data-client145-add]',workHost)?.addEventListener('click',()=>clientModal());$$('[data-client145-task]',workHost).forEach(b=>b.onclick=()=>clientModal(b.dataset.client145Task,true));$$('[data-client145-done]',workHost).forEach(b=>b.onclick=async()=>{const r=workData().consultingTasks.find(x=>x.id===b.dataset.client145Done);if(r){r.done=true;r.completedAt=Date.now();await save();renderWork(workHost,workBack,'task')}});
  }

  /* Brain and Speech engines are installed below in this file. */
  // -------------------------- 52-WEEK BRAIN --------------------------
  const BRAIN_KEY='aiderlog.offline.brain.v145';
  const BRAIN_OLD_KEY='aiderlog.offline.brain.v129';
  const BRAIN_DOMAINS={memory:['기억','사람·장면·이야기와 지연 회상'],working:['작업기억','순서·갱신·N-back'],attention:['주의력·처리속도','표적 선택과 방해 억제'],executive:['집행기능','규칙 전환과 계획'],spatial:['시공간','위치·경로·도형 회전'],reasoning:['추론·문제해결','패턴과 조건 조합']};
  let brainHost=null,brainBack=null,brainTab='today',brainRange=28;
  function baseBrain(){return{version:145,programStart:dateKey(),goalPerWeek:5,duration:12,autoDifficulty:true,sessions:[],activeSession:null,longRecall:[],difficulty:Object.fromEntries(Object.keys(BRAIN_DOMAINS).map(k=>[k,1])),settings:{font:'normal',contrast:false,colorAssist:false,reducedMotion:false,sound:true,vibration:true,hand:'right',reminder:'20:00',recallReminder:true},achievements:[],migration:{}}}
  function brainData(){
    let d;try{d=JSON.parse(localStorage.getItem(BRAIN_KEY)||'null')}catch{}
    if(!d||d.version!==145)d=baseBrain();
    d.sessions=Array.isArray(d.sessions)?d.sessions:[];d.longRecall=Array.isArray(d.longRecall)?d.longRecall:[];d.difficulty={...baseBrain().difficulty,...(d.difficulty||{})};
    if(!d.migration?.v129){
      try{const old=JSON.parse(localStorage.getItem(BRAIN_OLD_KEY)||'null');if(Array.isArray(old?.sessions))d.sessions.push(...old.sessions.map((s,i)=>({id:s.id||`legacy-${i}`,date:s.date||dateKey(),kind:'legacy',completed:s.completed!==false,duration:Number(s.duration)||0,domains:Object.entries(s.scores||{}).map(([domain,accuracy])=>({domain,accuracy:Number(accuracy)/100,difficulty:Number(old.difficulty?.[domain])||1,comparable:false})),appVersion:'v129 · migrated'})))}catch{}
      d.migration={...(d.migration||{}),v129:{at:Date.now(),sourceKey:BRAIN_OLD_KEY,backupKept:true}};brainSave(d);
    }
    return d;
  }
  function brainSave(d=brainData()){try{localStorage.setItem(BRAIN_KEY,JSON.stringify(d))}catch{}}
  function programDay(d=brainData()){const days=Math.max(0,Math.floor((new Date(`${dateKey()}T12:00:00`)-new Date(`${d.programStart}T12:00:00`))/86400000)),week=Math.min(52,Math.floor(days/7)+1);return{days,week,year:Math.floor(days/364)+1,season:Math.ceil(week/13),day:days%7+1}}
  function seasonName(n){return['적응과 기초','균형 강화','통합','안정화와 숙련'][n-1]||'적응과 기초'}
  function weekPlan(info=programDay()){const plans=[['memory','attention'],['working','spatial'],['executive','reasoning'],['memory','working'],['attention','executive','memory'],['spatial','reasoning'],[]];return plans[(info.day-1)%7]}
  function thisWeekSessions(d=brainData()){const start=new Date();start.setHours(0,0,0,0);start.setDate(start.getDate()-((start.getDay()+6)%7));return d.sessions.filter(s=>new Date(`${s.date}T12:00:00`)>=start&&s.completed)}
  function renderBrain(host,back){
    brainHost=host;brainBack=back;const d=brainData();
    if(d.activeSession){renderBrainSession();return}
    host.innerHTML=`<div class="page suite145-page brain145-page">${shellHead('OFFLINE COGNITIVE PROGRAM','Brain Training',back)}<nav class="suite145-tabs">${[['today','오늘'],['program','프로그램'],['free','자유 훈련'],['change','변화'],['achievements','성취'],['settings','설정']].map(([k,l])=>`<button class="${brainTab===k?'active':''}" data-brain-tab="${k}">${l}</button>`).join('')}</nav><div class="suite145-scroll">${brainTab==='today'?brainToday(d):brainTab==='program'?brainProgram(d):brainTab==='free'?brainFree(d):brainTab==='change'?brainChange(d):brainTab==='achievements'?brainAchievements(d):brainSettings(d)}</div></div>`;
    bindBrain();
  }
  function brainToday(d){
    const p=programDay(d),week=thisWeekSessions(d),done=Math.min(d.goalPerWeek,week.length),domains=weekPlan(p),recalls=d.longRecall.filter(r=>r.nextDate<=dateKey()&&r.state!=='long');
    return `<section class="brain145-program-head"><div><small>YEAR ${String(p.year).padStart(2,'0')} · SEASON ${p.season}</small><h2>${p.week} / 52주</h2><p>${seasonName(p.season)} · DAY ${p.day}</p></div><div class="brain145-orbit-progress" style="--progress:${Math.round(p.week/52*100)}%"><span><b>${Math.round(p.week/52*100)}%</b><small>연간</small></span></div></section><section class="suite145-card brain145-today"><header class="suite145-section-title"><div><small>TODAY · ${d.duration} MIN</small><h2>${p.day===7?'오늘은 회복일입니다':'오늘의 훈련'}</h2></div><span>${domains.length} AREAS</span></header>${p.day===7?'<div class="suite145-empty"><b>휴식도 프로그램의 일부예요.</b><p>원하면 자유 훈련이나 장기 회상을 진행할 수 있습니다.</p></div>':`<div class="brain145-route">${['기억 입력','주의력·처리속도','작업기억','집행·시공간','지연 회상'].map((x,i)=>`<span><i>${i+1}</i><b>${x}</b></span>`).join('')}</div><p class="suite145-callout">최근 수행을 바탕으로 영역별 난이도를 독립적으로 유지합니다. 한 번의 결과만으로 난이도를 바꾸지 않습니다.</p><button class="suite145-primary wide" data-brain-start="program">훈련 시작 · 약 ${d.duration}분</button>`}</section><section class="work145-grid"><article class="suite145-card"><header class="suite145-section-title"><div><small>THIS WEEK</small><h2>주간 현황</h2></div><b>${done} / ${d.goalPerWeek}</b></header><div class="brain145-week">${Array.from({length:7},(_,i)=>`<i class="${i<done?'done':i===done?'next':''}"><span>${['월','화','수','목','금','토','일'][i]}</span></i>`).join('')}</div><p class="suite145-muted">놓친 훈련은 연속 기록을 초기화하지 않고 남은 일정에 재배치합니다.</p></article><article class="suite145-card"><header class="suite145-section-title"><div><small>LONG RECALL</small><h2>장기 회상</h2></div><b>${recalls.length}</b></header><p>${recalls.length?`오늘 복습할 항목 ${recalls.length}개 · 약 ${Math.max(1,Math.ceil(recalls.length/3))}분`:'오늘 예정된 장기 회상이 없습니다.'}</p><button type="button" data-brain-start="recall" ${recalls.length?'':'disabled'}>복습 시작</button></article></section><section class="suite145-card"><header class="suite145-section-title"><div><small>ADAPTIVE GUIDE</small><h2>오늘의 난이도</h2></div></header><div class="brain145-guides">${domains.map(k=>`<p><b>${BRAIN_DOMAINS[k][0]}</b><span>${d.difficulty[k]}단계 · ${brainDifficultyCopy(d,k)}</span></p>`).join('')||'<p><b>회복일</b><span>다음 훈련에서도 현재 난이도를 유지합니다.</span></p>'}</div></section>`;
  }
  function brainDifficultyCopy(d,k){const comparable=d.sessions.filter(s=>s.domains?.some(x=>x.domain===k&&x.comparable!==false)).slice(-5);if(comparable.length<2)return'비교할 기록이 조금 더 필요합니다.';const avg=comparable.reduce((n,s)=>n+(s.domains.find(x=>x.domain===k)?.accuracy||0),0)/comparable.length;return avg>.82?'같은 난이도에서 반응이 안정적이었습니다.':avg<.55?'새로운 난이도에 적응 중입니다.':'다음 훈련에서도 현재 난이도를 유지합니다.'}
  function brainProgram(d){const p=programDay(d);return `<section class="suite145-card"><header class="suite145-section-title"><div><small>YEAR ${String(p.year).padStart(2,'0')}</small><h2>52주 프로그램</h2></div><span>현재 ${p.week}주차</span></header><div class="brain145-seasons">${[[1,'적응과 기초','기준선·정확도'],[2,'균형 강화','자극·방해 확장'],[3,'통합','영역 결합·긴 회상'],[4,'안정화와 숙련','약점 보완·연간 체크']].map(([n,name,copy])=>`<article class="${p.season===n?'active':''}"><span>SEASON ${n}</span><h3>${name}</h3><p>${(n-1)*13+1}–${n*13}주 · ${copy}</p><div><i style="width:${p.season>n?100:p.season===n?Math.round(((p.week-1)%13+1)/13*100):0}%"></i></div></article>`).join('')}</div><div class="brain145-weeks">${Array.from({length:52},(_,i)=>`<button type="button" class="${i+1<p.week?'done':i+1===p.week?'active':''}" data-brain-week="${i+1}"><b>${i+1}</b><small>${[1,5,9,13].includes((i%13)+1)?'CHECK':'TRAIN'}</small></button>`).join('')}</div></section>`}
  function brainFree(d){return `<section class="suite145-card"><header class="suite145-section-title"><div><small>FREE TRAINING</small><h2>원하는 영역 선택</h2></div><button type="button" data-brain-start="quick">빠른 3분</button></header><div class="brain145-domains">${Object.entries(BRAIN_DOMAINS).map(([k,[name,copy]])=>`<article><span>${String(d.difficulty[k]).padStart(2,'0')}</span><div><h3>${name}</h3><p>${copy}</p><small>최근 ${d.sessions.findLast?.(s=>s.domains?.some(x=>x.domain===k))?.date||'기록 없음'}</small></div><button type="button" data-brain-domain="${k}">시작</button></article>`).join('')}</div><p class="suite145-callout">자유 훈련은 일반 기록에는 저장하지만 정기 체크 결과에는 포함하지 않습니다.</p></section>`}
  function brainChange(d){const cutoff=Date.now()-brainRange*86400000,rows=d.sessions.filter(s=>new Date(`${s.date}T12:00:00`).getTime()>=cutoff&&s.completed);return `<nav class="brain145-range">${[[28,'4주'],[90,'3개월'],[180,'6개월'],[365,'1년']].map(([v,l])=>`<button class="${brainRange===v?'active':''}" data-brain-range="${v}">${l}</button>`).join('')}</nav><section class="work145-brief">${[['훈련일',new Set(rows.map(r=>r.date)).size],['완료 세션',rows.length],['중단',d.sessions.filter(s=>s.interrupted).length],['정기 체크',rows.filter(s=>s.kind==='check').length]].map(([l,v])=>`<article><span>${l}</span><strong>${v}</strong></article>`).join('')}</section><section class="suite145-card"><header class="suite145-section-title"><div><small>COMPARABLE CHANGE</small><h2>영역별 변화</h2></div></header><div class="brain145-change">${Object.entries(BRAIN_DOMAINS).map(([k,[name]])=>{const vals=rows.flatMap(s=>s.domains||[]).filter(x=>x.domain===k&&x.comparable!==false);const state=vals.length<5?'기록 부족':vals.slice(-3).reduce((n,x)=>n+x.accuracy,0)/Math.min(3,vals.length)>.78?'안정적':'적응 중';return `<article><b>${name}</b><span>${vals.length}회 · 현재 ${d.difficulty[k]}단계</span><strong>${state}</strong><small>${vals.length<5?'비교할 기록이 조금 더 필요합니다.':`같은 난이도 정확도 ${Math.round(vals.reduce((n,x)=>n+x.accuracy,0)/vals.length*100)}%`}</small></article>`}).join('')}</div></section>`}
  function brainAchievements(d){const p=programDay(d),days=new Set(d.sessions.filter(s=>s.completed).map(s=>s.date)).size,total=Math.round(d.sessions.reduce((n,s)=>n+(s.duration||0),0)/60);const badges=[['첫 훈련',d.sessions.length>=1],['첫 일주일',days>=5],['첫 4주',p.week>=5],['첫 시즌 완료',p.week>=14],['50회 훈련',d.sessions.length>=50],['6개 영역 경험',new Set(d.sessions.flatMap(s=>(s.domains||[]).map(x=>x.domain))).size>=6],['장기 회상 100개',d.longRecall.filter(x=>x.state==='long').length>=100],['6개월 지속',p.week>=27],['1년 완주',p.week>=52]];return `<section class="brain145-program-head compact"><div><small>YEAR ${String(p.year).padStart(2,'0')} · SEASON ${p.season}</small><h2>${p.week}주차</h2><p>${days}일 · ${total}분 · ${d.sessions.filter(s=>s.completed).length}세션</p></div><strong>${Math.round(p.week/52*100)}%</strong></section><section class="suite145-card"><header class="suite145-section-title"><div><small>LONG-TERM ACHIEVEMENT</small><h2>꾸준함의 기록</h2></div></header><div class="brain145-badges">${badges.map(([l,on])=>`<article class="${on?'earned':''}"><i>${on?icon('check',18):icon('brain',18)}</i><b>${l}</b><small>${on?'획득':'진행 중'}</small></article>`).join('')}</div></section>`}
  function brainSettings(d){const s=d.settings;return `<form class="suite145-card suite145-settings" data-brain-settings><header class="suite145-section-title"><div><small>TRAINING SETTINGS</small><h2>훈련 설정</h2></div></header><label>하루 훈련 시간<select name="duration">${[8,12,18].map(v=>`<option value="${v}" ${v===d.duration?'selected':''}>${v}분</option>`).join('')}</select></label><label>주간 목표<select name="goalPerWeek">${[3,4,5,6].map(v=>`<option value="${v}" ${v===d.goalPerWeek?'selected':''}>주 ${v}회</option>`).join('')}</select></label><label class="switch"><span>자동 난이도</span><input name="autoDifficulty" type="checkbox" ${d.autoDifficulty?'checked':''}></label><label>알림 시간<input name="reminder" type="time" value="${esc(s.reminder||'20:00')}"></label><label class="switch"><span>장기 회상 알림</span><input name="recallReminder" type="checkbox" ${s.recallReminder?'checked':''}></label><fieldset><legend>접근성</legend>${[['contrast','고대비'],['colorAssist','색각 보조'],['reducedMotion','애니메이션 감소'],['sound','효과음'],['vibration','진동']].map(([k,l])=>`<label class="switch"><span>${l}</span><input name="${k}" type="checkbox" ${s[k]?'checked':''}></label>`).join('')}</fieldset><footer><button type="button" data-brain-export>백업 내보내기</button><label class="file-button">복원<input type="file" data-brain-import accept="application/json"></label><button class="primary" type="submit">설정 저장</button></footer><button class="suite145-danger" type="button" data-brain-reset>전체 초기화</button></form>`}
  function startBrain(kind='program',domain=''){const d=brainData(),p=programDay(d),names=['민서','지우','서준','하린','도윤'],places=['도서관','공원','연구실','카페','기차역'],pick=Math.floor(Math.random()*names.length),sequence=Array.from({length:4+d.difficulty.working},()=>Math.floor(Math.random()*9)+1);d.activeSession={id:id('brain'),date:dateKey(),startedAt:Date.now(),kind,week:p.week,day:p.day,durationTarget:kind==='quick'?3:d.duration,step:0,steps:domain?[domain]:['memory','attention','working',p.week>=27?'reasoning':'executive','memory'],memory:{name:names[pick],place:places[(pick+2)%places.length],object:['파란 우산','은색 열쇠','노란 책'][pick%3]},sequence,responses:{},metrics:{attentionHits:0,attentionTargets:3,executiveCorrect:0},domain,appVersion:'v145'};brainSave(d);renderBrainSession()}
  function renderBrainSession(){const d=brainData(),s=d.activeSession;if(!s)return renderBrain(brainHost,brainBack);const step=s.step,labels=['기억 입력','주의력·처리속도','작업기억','집행기능·추론','지연 회상'];brainHost.innerHTML=`<div class="page suite145-page brain145-session"><header><button type="button" data-brain-exit>${icon('close')}</button><span><small>STEP ${step+1} / 5</small><b>${labels[step]}</b></span><button type="button" data-brain-pause>${icon('pause')}</button></header><div class="brain145-session-progress"><i style="width:${(step+1)/5*100}%"></i></div><main>${brainStep(s)}</main></div>`;bindBrainSession()}
  function brainStep(s){
    if(s.step===0)return `<section class="brain145-game"><small>기억 입력 · 마지막에 다시 묻습니다</small><h2>${esc(s.memory.name)}님은 ${esc(s.memory.place)}에<br>${esc(s.memory.object)}을 두었습니다.</h2><p>사람·장소·사물을 연결해 기억하세요. 바로 묻지 않고 다른 과제 뒤에 회상합니다.</p><button data-brain-next>기억했어요</button></section>`;
    if(s.step===1){const cells=['✦','○','○','✦','○','○','○','✦','○','○','○','○'];return `<section class="brain145-game"><small>방해 자극을 무시하세요</small><h2>빛나는 표적만 선택</h2><div class="brain145-targets">${cells.sort(()=>Math.random()-.5).map((v,i)=>`<button data-brain-target="${v==='✦'?1:0}" aria-label="표적 ${i+1}">${v}</button>`).join('')}</div><button data-brain-next>다음 단계</button></section>`}
    if(s.step===2)return `<section class="brain145-game"><small>숫자를 역순으로 입력하세요</small><h2 class="brain145-sequence">${s.sequence.join(' · ')}</h2><input data-brain-working inputmode="numeric" placeholder="예: ${s.sequence.slice().reverse().join('')}" value="${esc(s.responses.working||'')}"><button data-brain-next>입력 완료</button></section>`;
    if(s.step===3)return `<section class="brain145-game"><small>규칙 전환 · 글자가 아닌 색을 선택</small><h2><span style="color:#d95367">파랑</span>의 글자색은?</h2><div class="brain145-choices">${['빨강','파랑','초록','노랑'].map(v=>`<button data-brain-executive="${v}">${v}</button>`).join('')}</div><button data-brain-next>다음 단계</button></section>`;
    return `<section class="brain145-game"><small>지연 회상</small><h2>처음에 본 사람, 장소, 사물을 적어보세요.</h2><textarea data-brain-recall placeholder="기억나는 내용을 자유롭게 입력">${esc(s.responses.recall||'')}</textarea><button data-brain-finish>훈련 완료</button></section>`;
  }
  function finishBrain(){const d=brainData(),s=d.activeSession;if(!s)return;const answer=String(s.responses.recall||''),hits=[s.memory.name,s.memory.place,s.memory.object].filter(x=>answer.includes(x)).length,working=String(s.responses.working||'').replace(/\D/g,'')===s.sequence.slice().reverse().join(''),domains=[{domain:'memory',accuracy:hits/3,difficulty:d.difficulty.memory,comparable:true},{domain:'attention',accuracy:Math.min(1,s.metrics.attentionHits/s.metrics.attentionTargets),difficulty:d.difficulty.attention,comparable:true},{domain:'working',accuracy:working?1:0,difficulty:d.difficulty.working,comparable:true},{domain:s.week>=27?'reasoning':'executive',accuracy:s.metrics.executiveCorrect?1:0,difficulty:d.difficulty[s.week>=27?'reasoning':'executive'],comparable:true}];const row={id:s.id,date:s.date,kind:s.kind,week:s.week,day:s.day,completed:true,duration:Math.max(1,Math.round((Date.now()-s.startedAt)/1000)),domains,metrics:s.metrics,appVersion:'v145'};d.sessions.push(row);domains.forEach(x=>{const recent=d.sessions.flatMap(r=>r.domains||[]).filter(v=>v.domain===x.domain&&v.difficulty===x.difficulty).slice(-3);if(d.autoDifficulty&&recent.length>=3){const avg=recent.reduce((n,v)=>n+v.accuracy,0)/recent.length;if(avg>.84)d.difficulty[x.domain]=Math.min(10,d.difficulty[x.domain]+1);else if(avg<.48)d.difficulty[x.domain]=Math.max(1,d.difficulty[x.domain]-1)}});[1,3,7].forEach(days=>d.longRecall.push({id:id('recall'),sourceSession:s.id,prompt:`${s.memory.name} · ${s.memory.place} · ${s.memory.object}`,nextDate:addDays(days),state:'forming'}));d.activeSession=null;brainSave(d);renderBrainResult(row)}
  function renderBrainResult(r){brainHost.innerHTML=`<div class="page suite145-page">${shellHead('SESSION COMPLETE','훈련 결과',()=>{})}<div class="suite145-scroll"><section class="brain145-program-head compact"><div><small>${r.kind.toUpperCase()}</small><h2>${Math.max(1,Math.round(r.duration/60))}분</h2><p>${r.domains.length}개 영역 · 다음 복습 일정 생성</p></div><span>${icon('check',32)}</span></section><section class="suite145-card"><header class="suite145-section-title"><div><small>PERFORMED AREAS ONLY</small><h2>오늘 수행한 영역</h2></div></header><div class="brain145-results">${r.domains.map(x=>`<article><b>${BRAIN_DOMAINS[x.domain]?.[0]||x.domain}</b><strong>${Math.round(x.accuracy*100)}%</strong><span>${x.difficulty}단계</span><p>${x.accuracy>.8?'같은 난이도에서 반응이 안정적이었습니다.':x.accuracy>.5?'새로운 난이도에 적응 중입니다.':'다음 훈련에서도 현재 난이도를 유지합니다.'}</p></article>`).join('')}</div><p class="suite145-callout">수행하지 않은 영역은 점수를 만들지 않습니다. 충분한 동일 조건 기록이 쌓인 뒤에만 추세를 표시합니다.</p><button class="suite145-primary wide" data-brain-result-close>오늘 화면으로</button></section></div></div>`;const close=()=>{brainTab='today';renderBrain(brainHost,brainBack)};$('[data-suite145-back]',brainHost).onclick=close;$('[data-brain-result-close]',brainHost).onclick=close}
  function bindBrain(){
    $('[data-suite145-back]',brainHost)?.addEventListener('click',()=>brainBack?.());
    $$('[data-brain-tab]',brainHost).forEach(b=>b.onclick=()=>{brainTab=b.dataset.brainTab;renderBrain(brainHost,brainBack)});
    $$('[data-brain-start]',brainHost).forEach(b=>b.onclick=()=>startBrain(b.dataset.brainStart));
    $$('[data-brain-domain]',brainHost).forEach(b=>b.onclick=()=>startBrain('free',b.dataset.brainDomain));
    $$('[data-brain-range]',brainHost).forEach(b=>b.onclick=()=>{brainRange=Number(b.dataset.brainRange);renderBrain(brainHost,brainBack)});
    const form=$('[data-brain-settings]',brainHost);if(form)form.onsubmit=e=>{e.preventDefault();const d=brainData(),f=new FormData(form);d.duration=Number(f.get('duration'));d.goalPerWeek=Number(f.get('goalPerWeek'));d.autoDifficulty=!!f.get('autoDifficulty');['recallReminder','contrast','colorAssist','reducedMotion','sound','vibration'].forEach(k=>d.settings[k]=!!f.get(k));d.settings.reminder=String(f.get('reminder'));brainSave(d);(typeof toast==='function'?toast:alert)('Brain Training 설정을 저장했습니다.')};
    $('[data-brain-export]',brainHost)?.addEventListener('click',()=>downloadJson('AiderLog-Brain-backup.json',brainData()));
    $('[data-brain-import]',brainHost)?.addEventListener('change',e=>importJson(e.target.files?.[0],data=>{if(data?.version!==145)throw Error('v145 백업 파일이 아닙니다.');brainSave(data);renderBrain(brainHost,brainBack)}));
    $('[data-brain-reset]',brainHost)?.addEventListener('click',()=>{if(confirm('기존 v129 백업은 유지하고 v145 Brain 기록 전체를 초기화할까요?')){localStorage.removeItem(BRAIN_KEY);renderBrain(brainHost,brainBack)}});
  }
  function bindBrainSession(){const d=brainData(),s=d.activeSession;$('[data-brain-exit]',brainHost)?.addEventListener('click',()=>{if(confirm('현재 단계까지 저장하고 My로 나갈까요?'))brainBack?.()});$('[data-brain-pause]',brainHost)?.addEventListener('click',()=>alert('현재 단계가 저장되었습니다. 언제든 이어서 할 수 있어요.'));$$('[data-brain-target]',brainHost).forEach(b=>b.onclick=()=>{if(b.disabled)return;b.disabled=true;b.classList.add(b.dataset.brainTarget==='1'?'correct':'wrong');if(b.dataset.brainTarget==='1')s.metrics.attentionHits+=1;brainSave(d)});$$('[data-brain-executive]',brainHost).forEach(b=>b.onclick=()=>{s.metrics.executiveCorrect=b.dataset.brainExecutive==='빨강'?1:0;s.responses.executive=b.dataset.brainExecutive;$$('[data-brain-executive]',brainHost).forEach(x=>x.classList.toggle('selected',x===b));brainSave(d)});$('[data-brain-next]',brainHost)?.addEventListener('click',()=>{if(s.step===2)s.responses.working=$('[data-brain-working]',brainHost)?.value||'';s.step=Math.min(4,s.step+1);brainSave(d);renderBrainSession()});$('[data-brain-finish]',brainHost)?.addEventListener('click',()=>{s.responses.recall=$('[data-brain-recall]',brainHost)?.value||'';brainSave(d);finishBrain()})}
  function downloadJson(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
  async function importJson(file,done){if(!file)return;try{done(JSON.parse(await file.text()))}catch(e){alert(e.message||'백업 파일을 읽지 못했습니다.')}}

  // ----------------------- OFFLINE SPEECH ENGINE -----------------------
  const SPEECH_KEY='aiderlog.offline.speech.v145';
  const SPEECH_DB='aiderlog-speech-audio-v145';
  const SPEECH_TASKS=[
    {id:'meeting-delay-01',category:'직장',taskType:'제안',difficulty:4,timeLimit:60,prepTime:30,prompt:'회의 시간을 늦추자고 제안하세요.',context:'일부 팀원은 기존 시간 이후에 다른 일정이 있습니다.',goal:'변경 이유를 설명하고 동의를 구한다.',requiredElements:[['proposal','변경 제안',['늦추','변경','미루','조정']],['reason','변경 이유',['이유','때문','필요','일정']],['listenerConstraint','상대 제약 고려',['팀원','일정','어려운','불편']],['alternative','대안',['대안','가능하면','어렵다면','선택']]],followUps:{proposal:'무엇을 어떻게 변경하려는지 먼저 말해주세요.',reason:'회의 시간을 꼭 변경해야 하는 이유가 무엇인가요?',listenerConstraint:'기존 시간 이후 일정이 있는 사람은 어떻게 하나요?',alternative:'변경이 어려운 사람을 위한 대안은 무엇인가요?',all:'그 대안은 모든 사람에게 적용할 수 있나요?'}},
    {id:'research-qc-01',category:'연구',taskType:'설명',difficulty:5,timeLimit:75,prepTime:30,prompt:'실험 QC 기준 이탈과 재측정 필요성을 설명하세요.',context:'일정과 비용이 늘어날 수 있어 대표의 판단이 필요합니다.',goal:'관찰 사실, 위험, 대안과 다음 행동을 구분한다.',requiredElements:[['proposal','다음 행동',['재측정','확인','검토']],['reason','관찰 근거',['QC','기준','편차','결과']],['listenerConstraint','일정·비용 고려',['일정','비용','예산']],['alternative','대안',['대안','일부','우선','외부']]],followUps:{reason:'QC 기준을 벗어났다는 근거는 무엇인가요?',alternative:'전체 재측정 외에 가능한 대안이 있나요?',listenerConstraint:'일정과 비용에는 어떤 영향이 있나요?',proposal:'대표가 지금 결정해야 할 행동은 무엇인가요?',all:'반대 결과가 나왔을 때는 어떻게 판단하나요?'}},
    {id:'client-delay-01',category:'상담',taskType:'조율',difficulty:3,timeLimit:60,prepTime:30,prompt:'제출 일정이 늦어진 고객에게 보완 계획을 안내하세요.',context:'고객은 결과에 대한 불안이 높고 구체적인 일정을 원합니다.',goal:'상황을 인정하고 구체적 일정과 선택지를 제시한다.',requiredElements:[['proposal','보완 계획',['보완','계획','제출']],['reason','지연 설명',['지연','이유','확인']],['listenerConstraint','고객 감정 고려',['불안','걱정','기다','죄송']],['alternative','선택지',['선택','대안','먼저','가능']]],followUps:{reason:'왜 일정이 늦어졌는지 구체적으로 설명해주세요.',alternative:'고객이 기다리기 어렵다면 어떤 선택지가 있나요?',listenerConstraint:'고객의 불안을 어떻게 줄일 수 있나요?',proposal:'언제까지 무엇을 완료할지 말해주세요.',all:'그 계획을 확인할 수 있는 기준은 무엇인가요?'}},
    {id:'opinion-01',category:'일상',taskType:'의견',difficulty:2,timeLimit:45,prepTime:30,prompt:'재택근무가 더 효율적이라는 의견을 설명하세요.',context:'상대는 대면 협업이 더 중요하다고 생각합니다.',goal:'결론, 근거, 예외 조건과 확인 질문을 포함한다.',requiredElements:[['proposal','핵심 결론',['효율','생각','의견']],['reason','구체적 근거',['집중','시간','성과','이유']],['listenerConstraint','반대 의견 반영',['대면','협업','상대']],['alternative','조건·대안',['혼합','경우','조건','대안']]],followUps:{reason:'효율적이라고 판단한 구체적인 근거가 있나요?',alternative:'대면 협업이 필요한 경우는 어떻게 하나요?',listenerConstraint:'상대의 우려에 직접 답해주세요.',proposal:'당신의 결론을 한 문장으로 먼저 말해주세요.',all:'어떤 조건에서 의견이 달라질 수 있나요?'}}
  ];
  let speechHost=null,speechBack=null,speechTab='today',speechRecorder=null,speechStream=null,speechChunks=[],speechTimer=0;
  function speechBase(){return{version:145,programStart:dateKey(),sessions:[],activeSession:null,settings:{weeklyGoal:5,prepTime:30,autoDeleteDays:30,vibration:true,keepTranscript:true},migration:{v129:{at:Date.now(),preserved:true}}}}
  function speechData(){let d;try{d=JSON.parse(localStorage.getItem(SPEECH_KEY)||'null')}catch{}if(!d||d.version!==145)d=speechBase();d.sessions=Array.isArray(d.sessions)?d.sessions:[];d.settings={...speechBase().settings,...(d.settings||{})};return d}
  function speechSave(d=speechData()){try{localStorage.setItem(SPEECH_KEY,JSON.stringify(d))}catch{}}
  function speechProgram(d=speechData()){const days=Math.max(0,Math.floor((new Date(`${dateKey()}T12:00:00`)-new Date(`${d.programStart}T12:00:00`))/86400000)),week=Math.min(52,Math.floor(days/7)+1),season=Math.ceil(week/13);return{week,season,year:Math.floor(days/364)+1,name:['명료하게 말하기','근거와 구조','대화와 대응','설득과 조율'][season-1]}}
  function openSpeechDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open(SPEECH_DB,1);req.onupgradeneeded=()=>req.result.createObjectStore('audio');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
  async function audioPut(key,blob){const db=await openSpeechDb();return new Promise((resolve,reject)=>{const tx=db.transaction('audio','readwrite');tx.objectStore('audio').put(blob,key);tx.oncomplete=()=>{db.close();resolve(key)};tx.onerror=()=>reject(tx.error)})}
  async function audioGet(key){if(!key)return null;const db=await openSpeechDb();return new Promise((resolve,reject)=>{const req=db.transaction('audio').objectStore('audio').get(key);req.onsuccess=()=>{db.close();resolve(req.result||null)};req.onerror=()=>reject(req.error)})}
  async function audioDelete(key){if(!key)return;const db=await openSpeechDb();return new Promise(resolve=>{const tx=db.transaction('audio','readwrite');tx.objectStore('audio').delete(key);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();resolve()}})}
  function renderSpeech(host,back){speechHost=host;speechBack=back;const d=speechData();if(d.activeSession){renderSpeechSession();return}host.innerHTML=`<div class="page suite145-page speech145-page">${shellHead('PRIVATE · ON-DEVICE','Speech Training',back)}<nav class="suite145-tabs">${[['today','오늘'],['program','52주 프로그램'],['history','변화'],['settings','설정']].map(([k,l])=>`<button class="${speechTab===k?'active':''}" data-speech-tab="${k}">${l}</button>`).join('')}</nav><div class="suite145-scroll">${speechTab==='today'?speechToday(d):speechTab==='program'?speechProgramView(d):speechTab==='history'?speechHistory(d):speechSettings(d)}</div></div>`;bindSpeech()}
  function speechToday(d){const p=speechProgram(d),recent=d.sessions.slice(-10),comparable=recent.filter(s=>s.completed).length,task=SPEECH_TASKS[(p.week-1)%SPEECH_TASKS.length];return `<section class="speech145-hero"><div><small>YEAR ${String(p.year).padStart(2,'0')} · SEASON ${p.season}</small><h2>${p.week} / 52주</h2><p>${p.name}</p></div><span>${comparable<5?'기준선 수집':'개인 변화 확인'}</span></section><section class="suite145-card speech145-today"><header class="suite145-section-title"><div><small>TODAY · ${task.category} · ${task.taskType}</small><h2>${esc(task.prompt)}</h2></div><span>난이도 ${task.difficulty}</span></header><p>${esc(task.context)}</p><div class="speech145-flow">${['요구 확인','30초 준비','첫 답변','꼬리 질문','수정 답변','근거 비교'].map((x,i)=>`<span><i>${i+1}</i>${x}</span>`).join('')}</div><button class="suite145-primary wide" data-speech-start="${task.id}">${icon('mic',17)} 훈련 시작</button><small class="speech145-private">음성·변환문·평가는 기기 밖으로 전송되지 않습니다.</small></section><section class="work145-grid"><article class="suite145-card"><header class="suite145-section-title"><div><small>PERSONAL BASELINE</small><h2>개인 기준선</h2></div><b>${comparable}/5</b></header><p>${comparable<5?'처음 5–10회는 비교 기준을 모읍니다. 충분한 기록 전에는 향상·저하를 단정하지 않습니다.':'동일한 과제 유형과 인접 난이도끼리만 비교합니다.'}</p></article><article class="suite145-card"><header class="suite145-section-title"><div><small>THIS WEEK</small><h2>주간 훈련</h2></div><b>${d.sessions.filter(s=>daysBetween(s.date,dateKey())<7).length}/${d.settings.weeklyGoal}</b></header><p>핵심 능력 2회 · 대화 시뮬레이션 1회 · 약점 보완 1회 · 비교 훈련 1회</p></article></section>`}
  function speechProgramView(d){const p=speechProgram(d);return `<section class="suite145-card"><header class="suite145-section-title"><div><small>LONG-TERM SPEAKING</small><h2>52주 대화 훈련</h2></div><span>${p.week}주차</span></header><div class="brain145-seasons">${[['명료하게 말하기','결론과 직접 답변'],['근거와 구조','주장·근거·구체성'],['대화와 대응','반론·질문·상대 고려'],['설득과 조율','대안·합의·조건']].map((row,i)=>`<article class="${p.season===i+1?'active':''}"><span>SEASON ${i+1}</span><h3>${row[0]}</h3><p>${i*13+1}–${(i+1)*13}주 · ${row[1]}</p><div><i style="width:${p.season>i+1?100:p.season===i+1?Math.round(((p.week-1)%13+1)/13*100):0}%"></i></div></article>`).join('')}</div><div class="speech145-weekmap">${Array.from({length:52},(_,i)=>`<i class="${i+1<p.week?'done':i+1===p.week?'active':''}"><b>${i+1}</b><small>${[5,9,13].includes(i%13+1)?'CHECK':'TRAIN'}</small></i>`).join('')}</div></section>`}
  function speechHistory(d){const rows=d.sessions.slice().reverse();return `<section class="work145-brief">${[['완료 세션',rows.filter(r=>r.completed).length],['음성 기록',rows.filter(r=>r.first?.audioKey).length],['비교 가능',rows.filter(r=>r.comparison?.status!=='not_comparable').length],['기준선',Math.min(10,rows.length)]].map(([l,v])=>`<article><span>${l}</span><strong>${v}</strong></article>`).join('')}</section><section class="suite145-card"><header class="suite145-section-title"><div><small>EVIDENCE HISTORY</small><h2>첫 답변과 수정 답변</h2></div></header><div class="speech145-history">${rows.map(r=>`<article><span><b>${esc(r.taskPrompt||'대화 훈련')}</b><small>${esc(r.date)} · ${esc(r.category||'')} · 난이도 ${r.difficulty||'—'}</small></span><strong class="${r.comparison?.status||''}">${comparisonLabel(r.comparison?.status)}</strong><button data-speech-history-play="${esc(r.id)}">${icon('play',14)}</button><button data-speech-history-delete="${esc(r.id)}">${icon('trash',14)}</button></article>`).join('')||'<div class="suite145-empty"><b>아직 완료한 세션이 없습니다.</b></div>'}</div></section>`}
  function speechSettings(d){return `<form class="suite145-card suite145-settings" data-speech-settings><header class="suite145-section-title"><div><small>OFFLINE SETTINGS</small><h2>음성과 데이터</h2></div></header><label>주간 목표<select name="weeklyGoal">${[3,4,5,6].map(v=>`<option value="${v}" ${v===d.settings.weeklyGoal?'selected':''}>주 ${v}회</option>`).join('')}</select></label><label>답변 준비 시간<select name="prepTime">${[15,30,45,60].map(v=>`<option value="${v}" ${v===d.settings.prepTime?'selected':''}>${v}초</option>`).join('')}</select></label><label>원본 녹음 자동 삭제<select name="autoDeleteDays">${[[0,'삭제 안 함'],[7,'7일'],[30,'30일'],[90,'90일']].map(([v,l])=>`<option value="${v}" ${v===d.settings.autoDeleteDays?'selected':''}>${l}</option>`).join('')}</select></label><label class="switch"><span>변환문과 분석 보관</span><input name="keepTranscript" type="checkbox" ${d.settings.keepTranscript?'checked':''}></label><p class="suite145-callout">Android 온디바이스 모델이 없는 기기에서는 변환문 직접 입력을 사용합니다. 음성 신호 평가는 녹음 자체에서 계산합니다.</p><footer><button type="button" data-speech-export>백업 내보내기</button><label class="file-button">복원<input data-speech-import type="file" accept="application/json"></label><button class="primary">설정 저장</button></footer><button type="button" class="suite145-danger" data-speech-delete-all>Speech 데이터 전체 삭제</button></form>`}
  function daysBetween(a,b){return Math.abs((new Date(`${a}T12:00:00`)-new Date(`${b}T12:00:00`))/86400000)}
  function startSpeech(taskId){const d=speechData(),task=SPEECH_TASKS.find(t=>t.id===taskId)||SPEECH_TASKS[0];d.activeSession={id:id('speech'),date:dateKey(),taskId:task.id,stage:'brief',turn:1,startedAt:Date.now(),task:clone(task),first:{rawTranscript:'',editedTranscript:'',segments:[],averageConfidence:null,lowConfidenceSegments:[],audioKey:'',audioFeatures:null},revised:{rawTranscript:'',editedTranscript:'',segments:[],averageConfidence:null,lowConfidenceSegments:[],audioKey:'',audioFeatures:null},followUp:'',analysisFirst:null,analysisRevised:null};speechSave(d);renderSpeechSession()}
