  function bindSpeech(){ $('[data-suite145-back]',speechHost)?.addEventListener('click',()=>speechBack?.());$$('[data-speech-tab]',speechHost).forEach(b=>b.onclick=()=>{speechTab=b.dataset.speechTab;renderSpeech(speechHost,speechBack)});$$('[data-speech-start]',speechHost).forEach(b=>b.onclick=()=>startSpeech(b.dataset.speechStart));$$('[data-speech-history-delete]',speechHost).forEach(b=>b.onclick=async()=>{if(!confirm('세션과 연결된 원본 녹음을 삭제할까요?'))return;const d=speechData(),row=d.sessions.find(x=>x.id===b.dataset.speechHistoryDelete);await audioDelete(row?.first?.audioKey);await audioDelete(row?.revised?.audioKey);d.sessions=d.sessions.filter(x=>x.id!==b.dataset.speechHistoryDelete);speechSave(d);renderSpeech(speechHost,speechBack)});$$('[data-speech-history-play]',speechHost).forEach(b=>b.onclick=()=>{const row=speechData().sessions.find(x=>x.id===b.dataset.speechHistoryPlay);playRecording('revised',row).catch(()=>{})});const form=$('[data-speech-settings]',speechHost);if(form)form.onsubmit=e=>{e.preventDefault();const d=speechData(),f=new FormData(form);d.settings.weeklyGoal=Number(f.get('weeklyGoal'));d.settings.prepTime=Number(f.get('prepTime'));d.settings.autoDeleteDays=Number(f.get('autoDeleteDays'));d.settings.keepTranscript=!!f.get('keepTranscript');speechSave(d);(typeof toast==='function'?toast:alert)('Speech Training 설정을 저장했습니다.')};$('[data-speech-export]',speechHost)?.addEventListener('click',()=>downloadJson('AiderLog-Speech-backup.json',{...speechData(),note:'원본 음성은 개인정보 보호를 위해 JSON 백업에 포함되지 않습니다.'}));$('[data-speech-import]',speechHost)?.addEventListener('change',e=>importJson(e.target.files?.[0],data=>{if(data?.version!==145)throw Error('v145 백업 파일이 아닙니다.');speechSave(data);renderSpeech(speechHost,speechBack)}));$('[data-speech-delete-all]',speechHost)?.addEventListener('click',async()=>{if(!confirm('Speech Training 세션·분석·연결 음성을 모두 삭제할까요?'))return;const d=speechData();for(const s of d.sessions){await audioDelete(s.first?.audioKey);await audioDelete(s.revised?.audioKey)}localStorage.removeItem(SPEECH_KEY);renderSpeech(speechHost,speechBack)})}
  function bindSpeechSession(){const d=speechData(),s=d.activeSession;$('[data-speech-session-exit]',speechHost)?.addEventListener('click',()=>{if(confirm('현재 단계를 저장하고 My로 나갈까요?'))speechBack?.()});$$('[data-speech-stage]',speechHost).forEach(b=>b.onclick=()=>{s.stage=b.dataset.speechStage;speechSave(d);renderSpeechSession()});$$('[data-speech-record]',speechHost).forEach(b=>b.onclick=()=>startRecording(b.dataset.speechRecord));$('[data-speech-pause]',speechHost)?.addEventListener('click',pauseRecording);$('[data-speech-stop]',speechHost)?.addEventListener('click',stopRecording);$$('[data-speech-play]',speechHost).forEach(b=>b.onclick=()=>playRecording(b.dataset.speechPlay));$$('[data-speech-analyze]',speechHost).forEach(b=>b.onclick=()=>analyzeSpeechAnswer(b.dataset.speechAnalyze));$$('[data-speech-save-edit]',speechHost).forEach(b=>b.onclick=()=>{s[b.dataset.speechSaveEdit].editedTranscript=$(`[data-speech-edit="${b.dataset.speechSaveEdit}"]`,speechHost)?.value.trim()||'';s.analysisFirst=analyzeText(s.task,s.first.editedTranscript,s.first.audioFeatures);s.followUp=s.task.followUps[s.analysisFirst.missing[0]?.key||'all'];speechSave(d);renderSpeechSession()});$('[data-speech-complete]',speechHost)?.addEventListener('click',()=>{s.completed=true;s.completedAt=Date.now();s.taskPrompt=s.task.prompt;s.category=s.task.category;s.difficulty=s.task.difficulty;const row=clone(s);delete row.task;d.sessions.push(row);d.activeSession=null;speechSave(d);speechTab='today';renderSpeech(speechHost,speechBack)});const countdown=$('[data-speech-countdown]',speechHost);if(countdown){let left=Number(countdown.dataset.speechCountdown);const timer=setInterval(()=>{if(!countdown.isConnected)return clearInterval(timer);left=Math.max(0,left-1);countdown.textContent=left;if(!left)clearInterval(timer)},1000)}}
  document.addEventListener('visibilitychange',()=>{if(document.hidden&&speechRecorder?.state==='recording')stopRecording()});

  function counts(){
    const brain=brainData(),speech=speechData();
    return {brain:(brain.sessions||[]).length,speech:(speech.sessions||[]).length};
  }
  window.AiderLogSuiteV145={renderWork,renderBrain,renderSpeech,counts};
